// GENERATED by scripts/build-assets.mjs from src/core/cbm.js. Do not edit.
// CBM and shipment-size core. The container thresholds and wording follow the
// consolidation calculator on sourcefoshan.com (test/fixtures/site-consol-calc.js),
// and the parity tests run that site script against this module.

export class InputError extends Error {
  constructor(message) { super(message); this.name = 'InputError'; }
}

// Thresholds used by the site calculator (m³).
export const SHIPMENT_THRESHOLDS = Object.freeze({ lclBelow: 15, gp20Below: 28, hq40UpTo: 68 });

export const LIMITS = Object.freeze({
  maxLines: 200,
  maxQuantity: 100000,
  maxSideCm: 2000,
  maxCartonWeightKg: 5000,
  maxSupplierVolumes: 50,
  maxSupplierVolumeM3: 5000
});

const UNIT_TO_CM = Object.freeze({ cm: 1, mm: 0.1, m: 100, in: 2.54 });
const WEIGHT_TO_KG = Object.freeze({ kg: 1, lb: 0.45359237 });
const CUBIC_FEET_PER_M3 = 35.3146667;
export const DEFAULT_AIR_DIVISOR = 6000; // IATA standard, cm³ per kg

const round = (value, places) => {
  const f = 10 ** places;
  return Math.round((value + Number.EPSILON) * f) / f;
};

function positiveNumber(value, label, max) {
  const n = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) throw new InputError(`${label} must be a number greater than 0.`);
  if (max && n > max) throw new InputError(`${label} must be at most ${max}.`);
  return n;
}

/**
 * Suggest LCL / 20GP / 40HQ / several 40HQ for a total volume. With
 * basis 'quoted' (supplier volumes) the wording is the site calculator's;
 * 'packed' (measured cartons) drops the factory-figure caveats.
 * `suppliers` > 1 adds the "N suppliers, " prefix.
 */
export function suggestShipment(totalM3, suppliers = 0, basis = 'quoted') {
  const sum = totalM3;
  const packed = basis === 'packed';
  const s = suppliers > 1 ? suppliers + ' suppliers, ' : '';
  const quoted = 'about ' + sum.toFixed(1) + (packed ? ' m³ of packed cartons. ' : ' m³ quoted. ');
  const t = SHIPMENT_THRESHOLDS;
  if (sum < t.lclBelow) {
    return { mode: 'LCL', containers: 0, container_type: null,
      message: s + quoted + 'LCL (shared container) is the likely fit; under 5 m³ the fixed charges dominate, so combining with a later order can be worth it.' };
  }
  if (sum < t.gp20Below) {
    return { mode: '20GP', containers: 1, container_type: '20GP',
      message: s + quoted + (packed
        ? 'A 20-foot container (20GP) is the likely fit; close to 28 m³, a 40HQ may be cheaper per m³.'
        : 'A 20-foot container (20GP) is the likely fit once packed volume is measured; close to 28 m³, a 40HQ may be cheaper per m³.') };
  }
  if (sum <= t.hq40UpTo) {
    return { mode: '40HQ', containers: 1, container_type: '40HQ',
      message: s + quoted + (packed
        ? 'A 40-foot high-cube (40HQ) is the likely fit. Send us the packing lists for a loading review.'
        : 'A 40-foot high-cube (40HQ) is the likely fit. Packed volume usually runs 10–25% above factory figures, so send us the packing lists for a loading review.') };
  }
  const containers = Math.ceil(sum / t.hq40UpTo);
  const count = containers === 2 ? 'two' : String(containers);
  return { mode: 'MULTIPLE_40HQ', containers, container_type: '40HQ',
    message: s + quoted + 'That is more than one 40HQ: we plan ' + count + ' containers or phase the shipment around your installation schedule.' };
}

/** Site calculator mode: add up the volumes each supplier quoted. */
export function consolidate(volumes) {
  if (!Array.isArray(volumes) || volumes.length === 0) throw new InputError('supplier_volumes_m3 must be a non-empty list of volumes in m³.');
  if (volumes.length > LIMITS.maxSupplierVolumes) throw new InputError(`supplier_volumes_m3 can hold at most ${LIMITS.maxSupplierVolumes} volumes.`);
  let sum = 0;
  const clean = volumes.map((v, i) => {
    const n = positiveNumber(v, `supplier_volumes_m3[${i}]`, LIMITS.maxSupplierVolumeM3);
    sum += n; // same order of addition as the site script
    return n;
  });
  return {
    mode: 'supplier_volumes',
    suppliers: clean.length,
    total_cbm: round(sum, 3),
    total_cubic_feet: round(sum * CUBIC_FEET_PER_M3, 2),
    shipment: suggestShipment(sum, clean.length)
  };
}

/** Carton mode: CBM, weights and shipment size from carton dimensions. */
export function cartonCbm(cartons, options = {}) {
  const unit = options.unit ?? 'cm';
  const weightUnit = options.weight_unit ?? 'kg';
  const airDivisor = options.air_divisor ?? DEFAULT_AIR_DIVISOR;
  if (!(unit in UNIT_TO_CM)) throw new InputError(`unit must be one of: ${Object.keys(UNIT_TO_CM).join(', ')}.`);
  if (!(weightUnit in WEIGHT_TO_KG)) throw new InputError(`weight_unit must be one of: ${Object.keys(WEIGHT_TO_KG).join(', ')}.`);
  if (!Number.isInteger(airDivisor) || airDivisor < 1000 || airDivisor > 10000) throw new InputError('air_divisor must be a whole number between 1000 and 10000.');
  if (!Array.isArray(cartons) || cartons.length === 0) throw new InputError('cartons must be a non-empty list.');
  if (cartons.length > LIMITS.maxLines) throw new InputError(`cartons can hold at most ${LIMITS.maxLines} lines.`);

  const toCm = UNIT_TO_CM[unit];
  const toKg = WEIGHT_TO_KG[weightUnit];
  let totalM3 = 0, totalCartons = 0, totalKg = 0, totalVolKg = 0, weightsComplete = true;

  const lines = cartons.map((c, i) => {
    if (!c || typeof c !== 'object') throw new InputError(`cartons[${i}] must be an object with length, width and height.`);
    const maxSide = LIMITS.maxSideCm / toCm;
    const l = positiveNumber(c.length, `cartons[${i}].length`, maxSide) * toCm;
    const w = positiveNumber(c.width, `cartons[${i}].width`, maxSide) * toCm;
    const h = positiveNumber(c.height, `cartons[${i}].height`, maxSide) * toCm;
    const qty = c.quantity == null || c.quantity === '' ? 1 : positiveNumber(c.quantity, `cartons[${i}].quantity`, LIMITS.maxQuantity);
    if (!Number.isInteger(qty)) throw new InputError(`cartons[${i}].quantity must be a whole number.`);
    const cm3 = l * w * h;
    const m3Each = cm3 / 1e6;
    const volKgEach = cm3 / airDivisor;
    let kgEach = null;
    if (c.weight == null || c.weight === '') weightsComplete = false;
    else kgEach = positiveNumber(c.weight, `cartons[${i}].weight`, LIMITS.maxCartonWeightKg / toKg) * toKg;

    totalM3 += m3Each * qty;
    totalCartons += qty;
    totalVolKg += volKgEach * qty;
    if (kgEach != null) totalKg += kgEach * qty;

    return {
      line: i + 1,
      ...(c.label ? { label: String(c.label).slice(0, 120) } : {}),
      length_cm: round(l, 2), width_cm: round(w, 2), height_cm: round(h, 2),
      quantity: qty,
      cbm_per_carton: round(m3Each, 4),
      cbm: round(m3Each * qty, 4),
      gross_weight_kg: kgEach == null ? null : round(kgEach * qty, 2),
      air_volumetric_weight_kg: round(volKgEach * qty, 2)
    };
  });

  const totals = {
    cartons: totalCartons,
    cbm: round(totalM3, 4),
    cubic_feet: round(totalM3 * CUBIC_FEET_PER_M3, 2),
    gross_weight_kg: weightsComplete ? round(totalKg, 2) : null,
    air_volumetric_weight_kg: round(totalVolKg, 2),
    // Air: billed on the greater of actual and volumetric weight.
    air_chargeable_weight_kg: weightsComplete ? round(Math.max(totalKg, totalVolKg), 2) : null,
    // Sea LCL: billed per revenue ton, the greater of m³ and metric tonnes (W/M).
    sea_lcl_revenue_tons: weightsComplete ? round(Math.max(totalM3, totalKg / 1000), 3) : null
  };

  return {
    mode: 'cartons',
    input: { unit, weight_unit: weightUnit, air_divisor: airDivisor },
    lines,
    totals,
    ...(weightsComplete ? {} : { note: 'Add a gross weight to every carton line to get air chargeable weight and sea LCL revenue tons.' }),
    shipment: suggestShipment(totalM3, 0, 'packed')
  };
}

/** One entry point for both modes. */
export function calculate(input = {}) {
  const hasCartons = input.cartons != null;
  const hasVolumes = input.supplier_volumes_m3 != null;
  if (hasCartons === hasVolumes) throw new InputError('Send either cartons (carton dimensions) or supplier_volumes_m3 (volumes quoted by suppliers), not both.');
  return hasCartons ? cartonCbm(input.cartons, input) : consolidate(input.supplier_volumes_m3);
}
